sys_script_include.script:
var ReviewDataLoader = Class.create();
ReviewDataLoader.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getReview: function() {
        var emp = this.getParameter('sysparm_employee');
        var period = this.getParameter('sysparm_period');
		gs.info('emp' + emp);
		gs.info('period' + period);
        var gr = new GlideRecord('x_594089_employe_0_performance_review');
        gr.addQuery('employee', emp);
        gr.addQuery('review_period', period);
        gr.query();

        if (gr.next()) {
            var result = {
                assigned_task: gr.getValue('assigne_task'),
                completed_task: gr.getValue('completed_task'),
                pending_task: gr.getValue('pending_task'),
                self_review: gr.getValue('self_review'),
				manager_review: gr.getValue('manager_review') ? gr.getValue('manager_review') : '',
				manager_score: gr.getValue('manager_score') ? gr.getValue('manager_score') : ''
            };
			gs.info('gs.info(JSON.stringify(result));' + JSON.stringify(result));
            return JSON.stringify(result);
        }
        return JSON.stringify({});
    },
    type: 'ReviewDataLoader'
});
